118	static bool wdt_should_feed(void)
119	{
120	  bool cpu_ok;
121	  bool ui_req;
122	  bool ui_ok;
123	  bool idle_live;
124	  bool work_live;
125	  bool ui_live;
126	
127	  if (g_suppressed)
