129	      return false;
130	    }
131	
132	  idle_live = wdt_fresh(g_idle_beat);
133	  work_live = g_work_seen && wdt_fresh(g_work_beat);
134	  ui_live = g_ui_seen && wdt_fresh(g_ui_beat);
135	
136	  /* The UI beat comes from the bicycle_ui main loop. If it advances, the
137	   * scheduler and that application task are running even when a continuously
138	   * runnable task prevents up_idle() and no transfer updates the work beat.
139	   * Requiring idle/work alone reset a live board in this exact state. */
140	  cpu_ok = idle_live || work_live || ui_live;
141	  ui_req = wdt_ui_required_now();
142	  ui_ok = !ui_req || ui_live || work_live;
143	
144	  g_ui_required = ui_req;
145	  return cpu_ok && ui_ok;
146	}
