int main(int argc, FAR char *argv[])
{
  int spid = -1;
  int epid = -1;
  int tmp = -1;

  if (argc == 2)
    {
      spid = epid = atoi(argv[1]);
    }
  else if (argc >= 3)
    {
      spid = atoi(argv[1]);
      epid = atoi(argv[2]);
    }

  if (spid < 0 || epid < 0)
    {
      spid = epid = gettid();
    }

  if (spid > epid)
    {
      tmp = spid;
      spid = epid;
      epid = tmp;
    }

  do
    {
      sched_dumpstack(spid);
    }
  while (spid++ != epid);

  return 0;
}

 * snaps far from the true position) cannot spawn a replanning storm.  A large
 * jump from the previous reroute point is treated as a genuine deviation and
