static btn_buttonset_t lv_port_btn_read(void)
{
    btn_buttonset_t set = 0;
    ssize_t n;

    if (s_ctx.fd < 0) {
        return s_ctx.last;
    }

    n = read(s_ctx.fd, &set, sizeof(set));
    if (n == (ssize_t)sizeof(set)) {
        s_ctx.read_err = 0;
        return set;
    }

    if (s_ctx.read_err < 0xffffffffu) {
        s_ctx.read_err++;
