    /* 首次失败立刻报一次，之后 1 s 限频（重开失败也不是每拍刷屏）。 */
    if (lv_tick_elaps(s_ctx.last_err_log) >= 1000u) {
        s_ctx.last_err_log = lv_tick_get();
        syslog(LOG_WARNING, "btn: read failed n=%d errno=%d last=0x%02x err=%u\n",
