                 ? (uint32_t)SF32LB_SD_DEAD_RETRY_MS
                 : (uint32_t)SF32LB_SD_DEAD_RETRY_FAST_MS;

  if (!g_sd_revive_active
      && (now - g_sd_dead_try_us) >= (uint64_t)retry_ms * 1000ull)
    {
      sd1_schedule_revive();
    }

  return true;
}

